import json
import subprocess
import tempfile
import unittest
from pathlib import Path

from artifacts import deps

PIP_BEFORE = """\
#
# This file is autogenerated by pip-compile
#
certifi==2025.1.31
    # via requests
django==5.1.14
    # via
    #   -r requirements/base.in
    #   django-foo
Pillow==12.1.0
    # via -r requirements/base.in
requests==2.32.3
    # via -r requirements/base.in
"""

PIP_AFTER = PIP_BEFORE.replace('certifi==2025.1.31', 'certifi==2026.10.18').replace(
    'Pillow==12.1.0', 'Pillow==13.0.0'
)


def lockfile(qs_nested: str, pbkdf2: str) -> str:
    return json.dumps(
        {
            'lockfileVersion': 3,
            'packages': {
                '': {'dependencies': {'pbkdf2': '^3.1.0', 'url': '^0.11.0'}},
                'node_modules/pbkdf2': {'version': pbkdf2},
                'node_modules/qs': {'version': '6.17.1'},
                'node_modules/url': {'version': '0.11.4'},
                'node_modules/url/node_modules/qs': {'version': qs_nested},
                'node_modules/@scope/pkg': {'version': '1.0.0'},
                'node_modules/linked': {'link': True, 'resolved': '../linked'},
            },
        }
    )


class ParseTests(unittest.TestCase):
    def test_pip(self) -> None:
        found = {i.package: i for i in deps.parse_pip(PIP_BEFORE, 'requirements/base.txt')}
        self.assertEqual(set(found), {'certifi', 'django', 'pillow', 'requests'})
        self.assertEqual(found['certifi'].via, ('requests',))
        self.assertFalse(found['certifi'].direct)
        self.assertTrue(found['django'].direct)
        self.assertEqual(found['django'].via, ('django-foo',))
        self.assertEqual(found['pillow'].version, '12.1.0')

    def test_pip_includes_and_constraints_are_not_parents(self) -> None:
        text = (
            'urllib3==2.8.0\n    # via\n    #   -c requirements/base.txt\n    #   requests\n'
            'distlib==0.4.4\n    # via -r requirements/standards.txt\n'
            'pytest==8.0.0\n    # via -r requirements/dev.in\n'
        )
        found = {i.package: i for i in deps.parse_pip(text, 'requirements/dev.txt')}
        self.assertEqual(found['urllib3'].via, ('requests',))
        self.assertFalse(found['urllib3'].direct)
        self.assertEqual(found['distlib'].via, ())
        self.assertFalse(found['distlib'].direct)
        self.assertTrue(found['pytest'].direct)

    def test_pip_url_requirement_does_not_lend_its_via(self) -> None:
        text = (
            'dnspython==2.9.0 \\\n    --hash=sha256:abc\n    # via pymongo\n'
            'internal-tools @ https://example.com/internal-tools.zip \\\n    --hash=sha256:def\n'
            '    # via -r requirements/base.in\n'
        )
        found = {i.package: i for i in deps.parse_pip(text, 'requirements/base.txt')}
        self.assertEqual(set(found), {'dnspython'})
        self.assertFalse(found['dnspython'].direct)
        self.assertEqual(found['dnspython'].via, ('pymongo',))

    def test_npm(self) -> None:
        found = deps.parse_npm(lockfile('6.16.0', '3.1.6'), 'client/package-lock.json')
        by_location = {(i.package, i.copy): i for i in found}
        self.assertTrue(by_location[('pbkdf2', None)].direct)
        self.assertFalse(by_location[('qs', None)].direct)
        self.assertEqual(by_location[('qs', 'url > qs')].version, '6.16.0')
        self.assertEqual(by_location[('qs', 'url > qs')].via, ('url',))
        self.assertIn(('@scope/pkg', None), by_location)
        self.assertNotIn(('linked', None), by_location)

    def test_npm_v1_is_refused(self) -> None:
        with self.assertRaisesRegex(ValueError, 'only npm lockfile versions 2 and 3'):
            deps.parse_npm('{"lockfileVersion": 1, "dependencies": {}}', 'package-lock.json')


class VersionTests(unittest.TestCase):
    def test_ordering(self) -> None:
        ordered = ['1.0.0rc1', '1.0.0', '1.0.0.post1', '1.0.1', '1.10.0', '2.0.0-beta.2', '2.0.0']
        keys = [deps.version_key(v) for v in ordered]
        self.assertEqual(keys, sorted(keys))
        self.assertEqual(deps.version_key('1.2'), deps.version_key('1.2.0'))

    def test_unorderable(self) -> None:
        with self.assertRaises(ValueError):
            deps.version_key('nightly')

    def test_ranges(self) -> None:
        self.assertTrue(deps.in_range('2.1.0', '>= 2.0.0, < 2.2.2'))
        self.assertFalse(deps.in_range('2.2.2', '>= 2.0.0, < 2.2.2'))
        self.assertTrue(deps.in_range('1.0.0', '= 1.0.0'))
        self.assertTrue(deps.in_range('12.1.0', '< 13.0.0'))
        with self.assertRaises(ValueError):
            deps.in_range('1.0', '~> 1.0')

    def test_major(self) -> None:
        self.assertTrue(deps.is_major('12.1.0', '13.0.0'))
        self.assertFalse(deps.is_major('6.16.0', '6.17.1'))
        self.assertTrue(deps.is_major('0.3.9', '0.4.4'))
        self.assertFalse(deps.is_major(None, '1.0.0'))

    def test_calendar_versions_are_never_major(self) -> None:
        self.assertFalse(deps.is_major('2025.1.31', '2026.10.18'))  # certifi
        self.assertFalse(deps.is_major('20250101', '20260101'))


class RepoTests(unittest.TestCase):
    """Against a real git repository: base commit, then the upgrade in the working tree."""

    def setUp(self) -> None:
        self._tmp = tempfile.TemporaryDirectory()
        self.repo = Path(self._tmp.name)
        (self.repo / 'requirements').mkdir()
        (self.repo / 'client').mkdir()
        self._write(PIP_BEFORE, lockfile('6.16.0', '3.1.6'))
        (self.repo / 'requirements' / 'dev.txt').write_text(
            'certifi==2025.1.31\n    # via requests\n'
        )
        git = ['git', '-C', str(self.repo), '-c', 'user.name=t', '-c', 'user.email=t@example.com']
        subprocess.run([*git, 'init', '-q'], check=True)
        subprocess.run([*git, 'add', '.'], check=True)
        subprocess.run([*git, 'commit', '-q', '-m', 'base'], check=True)
        self._write(PIP_AFTER, lockfile('6.17.1', '3.1.6'))
        (self.repo / 'requirements' / 'dev.txt').write_text(
            'certifi==2026.10.18\n    # via requests\n'
        )

    def tearDown(self) -> None:
        self._tmp.cleanup()

    def _write(self, pip: str, npm: str) -> None:
        (self.repo / 'requirements' / 'base.txt').write_text(pip)
        (self.repo / 'client' / 'package-lock.json').write_text(npm)

    def _state(self, ref: str) -> list[deps.Installed]:
        return deps.read_state(self.repo, ref, ['requirements/*.txt'], ['client/package-lock.json'])

    def test_diff_groups_manifests_and_includes_transitive_moves(self) -> None:
        changed = deps.diff(self._state('HEAD'), self._state(deps.WORKTREE))
        by_package = {(c['package'], c['copy']): c for c in changed}
        self.assertEqual(set(by_package), {('certifi', None), ('pillow', None), ('qs', 'url > qs')})
        self.assertEqual(
            by_package[('certifi', None)]['manifests'],
            ['requirements/base.txt', 'requirements/dev.txt'],
        )
        self.assertEqual(by_package[('pillow', None)]['before'], '12.1.0')
        self.assertTrue(by_package[('pillow', None)]['direct'])

    def test_alerts_closed_only_when_every_copy_is_fixed(self) -> None:
        def alert(
            number: int, ecosystem: str, name: str, manifest: str, vulnerable: str, severity: str
        ) -> dict:
            return {
                'number': number,
                'state': 'open',
                'dependency': {
                    'package': {'ecosystem': ecosystem, 'name': name},
                    'manifest_path': manifest,
                },
                'security_advisory': {'severity': severity},
                'security_vulnerability': {'vulnerable_version_range': vulnerable},
            }

        alerts = [
            alert(1, 'pip', 'Pillow', 'requirements/base.txt', '< 13.0.0', 'critical'),
            alert(2, 'npm', 'qs', 'client/package-lock.json', '< 6.17.0', 'moderate'),
            alert(3, 'npm', 'pbkdf2', 'client/package-lock.json', '< 3.1.7', 'high'),
            alert(4, 'pip', 'django', 'requirements/base.txt', '>= 5.2, < 5.2.16', 'high'),
            alert(5, 'pip', 'requests', 'requirements/base.txt', '~> 2.0', 'low'),
        ]
        base = self._state('HEAD')
        result = deps.closed_alerts(alerts, base, self._state(deps.WORKTREE))
        self.assertEqual([a['number'] for a in result['closed']], [1, 2])
        # django 5.1.14 was never in this range: not something this change closed.
        self.assertEqual([a['number'] for a in result['already_fixed']], [4])
        self.assertEqual([a['number'] for a in result['undecided']], [5])
        self.assertEqual(result['open_before'], {'critical': 1, 'high': 2, 'medium': 1, 'low': 1})

        # One vulnerable nested copy keeps the qs alert open.
        self._write(PIP_AFTER, lockfile('6.16.0', '3.1.6'))
        result = deps.closed_alerts(alerts, base, self._state(deps.WORKTREE))
        self.assertNotIn(2, [a['number'] for a in result['closed']])

    def test_load_alerts_flattens_slurped_pages(self) -> None:
        pages = json.dumps([[{'number': 1, 'state': 'open'}], [{'number': 2, 'state': 'fixed'}]])
        self.assertEqual([a['number'] for a in deps.load_alerts(pages)], [1])

    def test_load_alerts_reads_pages_written_back_to_back(self) -> None:
        # What `gh api --paginate` writes without --slurp: one array per page, not one document.
        pages = '[{"number": 1, "state": "open"}]\n[{"number": 2, "state": "open"}]'
        self.assertEqual([a['number'] for a in deps.load_alerts(pages)], [1, 2])

    def test_load_alerts_reads_one_alert_per_line(self) -> None:
        lines = '{"number": 1, "state": "open"}\n{"number": 2, "state": "dismissed"}\n'
        self.assertEqual([a['number'] for a in deps.load_alerts(lines)], [1])

    def test_load_alerts_refuses_damaged_output(self) -> None:
        with self.assertRaisesRegex(ValueError, 'not valid JSON'):
            deps.load_alerts('[{"number": 1}][{"numb')
        with self.assertRaisesRegex(ValueError, 'arrays or objects'):
            deps.load_alerts('42')


if __name__ == '__main__':
    unittest.main()
